  "revision_action": "strengthen",
  "supportive_card_ids": ["C07","C14","C17","C03","C06","C12","C21","C23","C28","C29","C32","C33","C35"],
  "contradictory_card_ids": ["C04","C19","C24"],
  "prediction_basis_card_ids": ["C07","C14","C17","C03","C06","C12","C21","C23","C28"],
  "claims": [
    {
      "claim": "The query is a fentanyl-class 4-anilidopiperidine; the closest measured opioid context, meperidine, had F=0.80 in cirrhosis (C07, C14), and L2 indicates cirrhosis increases its systemic availability by 81% (C17), implying a normal-condition estimate still above the 20% threshold.",
      "card_ids": ["C07","C14","C17"]
    },
    {
      "claim": "Encainide, a piperidine anilide, had F=76-78% in cirrhosis (C03, C06, C12), with F=0.52 in a poor-metabolizer cirrhotic patient (C23) and >2-fold higher than healthy extensive metabolizers (C21), supporting high F for this piperidine amide class.",
      "card_ids": ["C03","C06","C12","C21","C23"]
    },
    {
      "claim": "L3 oral exposure records for fentanyl (C28) and fentanyl-class LASSBio-1736 in rats (C29, C32, C33, C35) show measurable systemic exposure after oral dosing, consistent with oral absorption and supporting the high prediction direction, though they do not quantify F.",
      "card_ids": ["C28","C29","C32","C33","C35"]
    },
    {
      "claim": "The meptazinol context (C04, C19, C24) implies low normal F but is structurally dissimilar (phenolic azepane) and has low transferability; it does not affirmatively establish F<20% for the query.",
      "card_ids": ["C04","C19","C24"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C28","C29","C32","C33","C35"]
    },
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C25","C26","C27","C30","C31","C34","C36"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule.",
    "L3 fentanyl oral exposure records lack an IV comparator, so F cannot be quantified from them.",
    "The closest opioid contexts were measured in cirrhosis; normal-condition F must be inferred from disease-effect statements (C17, C19) with uncertainty.",
    "No data on query-specific first-pass metabolism, efflux, or solubility-limited absorption.",
    "No human PK data for this specific fentanyl analog."
  ],
  "decision_summary": "Prediction remains high: meperidine and encainide contexts support F>20% even after adjusting for cirrhosis-related increases, and L3 fentanyl oral exposure records add supportive evidence of oral absorption for the fentanyl scaffold. No affirmative threshold-relevant evidence supports F<20%; the meptazinol context is structurally dissimilar and low-transferability. Confidence is raised to moderate."
}

